/* the pot sections' values (val[6..]) for the knobs k; val[0..5] come from mks_pi_load.h (PRES) */
static inline void mks_mna_pot_values(const MksMnaKnobs* k, double* val)
{
    bn_preamp_ckt_pot_values(k->VOL, k->TREB, k->BASS, k->MID, k->MASTER, &val[6], MKS_MK81_US_POTS);   /* MK 81's laws */
    val[15] = 22e3 * (1.0 - k->PRES) + 1.0;                                    /* VR6 presence (power.py) */
    { const double* jv = k->LOWIN > 0.5 ? BN_PREAMP_CKT_JACK_LOW : BN_PREAMP_CKT_JACK_HIGH;
      for (int j = 0; j < BN_PREAMP_CKT_N_JACK; ++j) { val[16 + j] = jv[j]; } }
}
